import { seedWorktreeChat } from './seedWorktreeChat.mjs';

/**
 * Seed one undelivered input-delivery row whose text is a cloud watcher
 * wake-up: the instruction block with the event, then the short notice.
 */
export const WATCHER_NOTICE_PROJECT_ID = 'demo-ts-pnpm-vite';
export const WATCHER_NOTICE_WORKTREE_ID = 'demo-main';
const CHAT_ID = 'watcher-notice-row';
const ROW_ID = 'watcher-notice';

const FIRED_TEXT = [
  '<system_instruction>',
  'Canopy watcher internal event details. This message was generated by Canopy, not typed by the user. Use these details to respond to the watcher event. Do not show the raw watcher payload or internal ids unless the user explicitly asks for debugging details.',
  '',
  '<canopy_watcher_event>',
  JSON.stringify(
    {
      watcherId: '33875e8f-c6d7-58b2-8a3b-0137335c92ae',
      label: 'Dark mode plan finished',
      trigger: 'worktree_chat_completion',
      target: {
        kind: 'worktree_chat',
        projectId: 'workspace-1',
        worktreeId: 'task-1',
        chatId: 'chat-1',
      },
      event: {
        outcome: 'completed',
        status: 'WAITING_FOR_USER',
        finalMessage: 'The plan is ready for review.',
      },
      followUpInstruction: 'Review the latest agent response',
    },
    null,
    2,
  ),
  '</canopy_watcher_event>',
  '</system_instruction>',
  '',
  'Canopy watcher fired.',
  'Dark mode plan finished',
].join('\n');

export function seedWatcherNoticeRow(userDataDir) {
  seedWorktreeChat({
    userDataDir,
    workspaceId: WATCHER_NOTICE_PROJECT_ID,
    worktreeId: WATCHER_NOTICE_WORKTREE_ID,
    activeTabId: CHAT_ID,
    providerType: 'claude',
    tabs: [
      {
        id: CHAT_ID,
        title: 'Watcher notice',
        messages: [
          {
            id: 'seeded-assistant',
            role: 'assistant',
            timestamp: 500,
            blocks: [{ type: 'text', text: 'Started the helper.' }],
          },
        ],
        inputDelivery: {
          version: 1,
          epoch: 0,
          rows: [
            {
              id: ROW_ID,
              revision: 1,
              createdAt: 1_000,
              state: 'uncertain',
              text: FIRED_TEXT,
              settingsKey: 'seeded',
              payload: {
                projectId: WATCHER_NOTICE_PROJECT_ID,
                worktreeId: WATCHER_NOTICE_WORKTREE_ID,
                chatId: CHAT_ID,
                userMessageId: ROW_ID,
                text: FIRED_TEXT,
              },
              currentAttemptId: `attempt-${ROW_ID}`,
              attempts: [
                {
                  id: `attempt-${ROW_ID}`,
                  generation: 'ended-session',
                  provider: 'claude',
                  createdAt: 1_000,
                  admittedAt: 1_001,
                  uncertainAt: 2_000,
                },
              ],
            },
          ],
        },
      },
    ],
  });
}
